let budget = 1000;     // starting interrupt budget
const CALL_COST = 1;   // entering the function
const EDGE_COST = 1;   // one backward jump (loop iteration)
const ITERS = 300;     // loop iterations per call

let totalBackEdges = 0;
let tierUpCall = 0;
let tierUpEdge = 0;

for (let call = 1; call <= 4 && tierUpCall === 0; call++) {
  budget -= CALL_COST;
  for (let i = 0; i < ITERS; i++) {
    budget -= EDGE_COST;
    totalBackEdges++;
    if (budget <= 0 && tierUpCall === 0) {
      tierUpCall = call;
      tierUpEdge = totalBackEdges;
    }
  }
}

console.log('tierUpEdge=' + tierUpEdge + ' tierUpCall=' + tierUpCall);

