function tierUpEdge(startBudget, edges) {
  let budget = startBudget;
  for (let edge = 1; edge <= edges; edge++) {
    budget -= 1;            // spend one back-edge
    if (budget < 0) {       // trip condition
      return edge;
    }
  }
  return -1;
}

