diff.code:
function run(program) {
  const stack = [];
  let pc = 0;
  while (pc < program.length) {
    const op = program[pc];
    switch (op.code) {
      case 'PUSH':
        stack.push(op.value);
        break;
      case 'ADD': {
        const a = stack.pop();
        const b = stack.pop();
        stack.push(a + b);
        break;
      }
      case 'JUMP':
        pc = op.target;        // jump, then fall through to pc++
      case 'PRINT':
        console.log(stack[stack.length - 1]);
        break;
    }
    pc++;
  }
  return stack;
}
